// @pit: {"label": "Document imitated-call notice in CHANGELOG and docs/reference.md"}
async ({ workspace: { read, batch } }, p: { cl: string; ref: string }) => {
  const r = await read("docs/reference.md", { offset: 129, limit: 1 });
  const line = r.content.replace(/^129:[^|]+\|/, "");
  const marker = "An entry no larger than its stub, and an assistant entry without tool calls, are rejected.";
  if (!line.includes(marker)) throw new Error("marker missing");
  return batch([
    { kind: "edit", file: "CHANGELOG.md", changes: { revision: "tbs2nHYYT2dr", changes: [{ kind: "insertAfter", anchor: "5:HaQuG", content: p.cl }] } },
    { kind: "edit", file: "docs/reference.md", changes: { revision: r.revision, changes: [{ kind: "replace", start: "129:-kA4G", content: line.replace(marker, marker + p.ref) }] } },
  ]) as any;
}
